for(ii in 1:nrow(comparisons)) {cp<-comparisons[ii];res<-fread(out(paste0('02_pseudobulk_markers/',cp$comparison,'_DE_full.tsv.gz')));dscols<-grep('^dataset_delta_',names(res),value=TRUE)
