 if(cp$comparison=='r06_C12_vs_C16') {for(side in c('Left','Right')){gg<-head(res[eligible_shortlist==TRUE & orientation==side,gene_id],10);res[gene_id%in%gg,selected:=TRUE]}}else{gg<-head(res[eligible_shortlist==TRUE,gene_id],20);res[gene_id%in%gg,selected:=TRUE]};res[eligible_shortlist==TRUE & selected==FALSE,selection_reason:='qualified but below fixed shortlist limit'];wt(res[,.(gene_id,eligible_shortlist,selected,orientation,selection_reason,dataset_direction_fraction,direction_fraction,target_detection,oriented_detection_delta,absolute_effect)],paste0('03_marker_review/',cp$comparison,'_selection_alltested.tsv.gz'));wt(res[selected==TRUE],paste0('03_marker_review/',cp$comparison,'_shortlist.tsv'))
